120	// ---------------------------------------------------------------------------
121	// 数据模型与文件存取
122	// ---------------------------------------------------------------------------
123	
124	type ResourceType = 'venue' | 'equipment' | 'person';
125	type BookingStatus = 'active' | 'cancelled';
126	
127	interface ResourceRec {
128	  id: string;
129	  type: ResourceType;
130	  name: string;
131	  open: Array<[string, string]>;
132	}
133	
134	interface BookingRec {
135	  id: string;
136	  resourceIds: string[];
137	  start: string;
138	  end: string;
139	  status: BookingStatus;
140	}
141	
142	interface Store {
143	  version: 1;
144	  resourceSeq: number;
145	  bookingSeq: number;
146	  resources: ResourceRec[];
147	  bookings: BookingRec[];
148	}
149	
150	const RESOURCE_TYPE_LABEL: Record<ResourceType, string> = {
151	  venue: '场地',
152	  equipment: '设备',
153	  person: '人员',
154	};
155	
156	const RESOURCE_TYPE_MAP: Record<string, ResourceType> = {
157	  venue: 'venue',
158	  equipment: 'equipment',
159	  person: 'person',
160	  '场地': 'venue',
161	  '设备': 'equipment',
162	  '人员': 'person',
163	};
164	
165	function emptyStore(): Store {
166	  return {version: 1, resourceSeq: 0, bookingSeq: 0, resources: [], bookings: []};
167	}
168	
169	function isInt(v: unknown): v is number {
170	  return typeof v === 'number' && Number.isInteger(v) && v >= 0;
171	}
172	
173	// 严格校验数据文件结构；非法时抛出 BizError，调用方不得写回文件
174	function validateStore(raw: unknown, file: string): Store {
175	  const bad = (reason: string): never => {
176	    throw new BizError(`数据文件 ${file} 结构非法：${reason}（原文件已保留，未做修改）`);
177	  };
178	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) bad('顶层必须是对象');
179	  const o = raw as Record<string, unknown>;
180	
181	  if (o.version !== undefined && o.version !== 1) bad(`不支持的版本: ${String(o.version)}`);
182	
183	  const store = emptyStore();
184	  if (o.resourceSeq !== undefined) {
185	    if (!isInt(o.resourceSeq)) bad('resourceSeq 必须是非负整数');
186	    store.resourceSeq = o.resourceSeq;
187	  }
188	  if (o.bookingSeq !== undefined) {
189	    if (!isInt(o.bookingSeq)) bad('bookingSeq 必须是非负整数');
190	    store.bookingSeq = o.bookingSeq;
191	  }
192	
193	  if (o.resources !== undefined && !Array.isArray(o.resources)) bad('resources 必须是数组');
194	  if (o.bookings !== undefined && !Array.isArray(o.bookings)) bad('bookings 必须是数组');
195	  const rawResources = (o.resources ?? []) as unknown[];
196	  const rawBookings = (o.bookings ?? []) as unknown[];
197	
198	  const resourceIds = new Set<string>();
199	  rawResources.forEach((item, idx) => {
200	    const at = `resources[${idx}]`;
201	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
202	    const r = item as Record<string, unknown>;
203	    if (typeof r.id !== 'string' || !/^R\d{4,}$/.test(r.id)) bad(`${at}.id 非法: ${String(r.id)}`);
204	    if (resourceIds.has(r.id)) bad(`资源标识重复: ${r.id}`);
205	    resourceIds.add(r.id);
206	    if (r.type !== 'venue' && r.type !== 'equipment' && r.type !== 'person') {
207	      bad(`${at}(${r.id}).type 非法: ${String(r.type)}`);
208	    }
209	    if (typeof r.name !== 'string' || r.name.trim() === '') bad(`${at}(${r.id}).name 不能为空`);
210	    if (!Array.isArray(r.open) || r.open.length === 0) bad(`${at}(${r.id}).open 必须是非空数组`);
211	    const open: Array<[string, string]> = [];
212	    r.open.forEach((iv: unknown, j: number) => {
213	      if (!Array.isArray(iv) || iv.length !== 2 || typeof iv[0] !== 'string' || typeof iv[1] !== 'string') {
214	        bad(`${at}(${r.id}).open[${j}] 必须是 [开始, 结束]`);
215	      }
216	      const s = parseDateTime(iv[0], `${at}(${r.id}).open[${j}] 开始时间`);
217	      const e = parseDateTime(iv[1], `${at}(${r.id}).open[${j}] 结束时间`);
218	      if (e <= s) bad(`${at}(${r.id}).open[${j}] 结束必须晚于开始`);
219	      open.push([iv[0], iv[1]]);
220	    });
221	    store.resources.push({id: r.id, type: r.type, name: r.name, open});
222	    const n = Number(r.id.slice(1));
223	    if (n > store.resourceSeq) store.resourceSeq = n;
224	  });
225	
226	  const bookingIds = new Set<string>();
227	  rawBookings.forEach((item, idx) => {
228	    const at = `bookings[${idx}]`;
229	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
230	    const b = item as Record<string, unknown>;
231	    if (typeof b.id !== 'string' || !/^B\d{4,}$/.test(b.id)) bad(`${at}.id 非法: ${String(b.id)}`);
232	    if (bookingIds.has(b.id)) bad(`预约标识重复: ${b.id}`);
233	    bookingIds.add(b.id);
234	    if (!Array.isArray(b.resourceIds) || b.resourceIds.length === 0) {
235	      bad(`${at}(${b.id}).resourceIds 必须是非空数组`);
236	    }
237	    const ids = b.resourceIds as unknown[];
238	    const seen = new Set<string>();
239	    ids.forEach((rid) => {
240	      if (typeof rid !== 'string' || !resourceIds.has(rid)) {
241	        bad(`${at}(${b.id}) 引用了未知资源: ${String(rid)}`);
242	      }
243	      if (seen.has(rid)) bad(`${at}(${b.id}) 资源重复: ${rid}`);
244	      seen.add(rid);
245	    });
246	    if (typeof b.start !== 'string' || typeof b.end !== 'string') {
247	      bad(`${at}(${b.id}) 起止时间必须是字符串`);
248	    }
249	    const s = parseDateTime(b.start, `${at}(${b.id}).start`);
250	    const e = parseDateTime(b.end, `${at}(${b.id}).end`);
251	    if (e <= s) bad(`${at}(${b.id}) 结束必须晚于开始`);
252	    if (b.status !== 'active' && b.status !== 'cancelled') {
253	      bad(`${at}(${b.id}).status 非法: ${String(b.status)}`);
254	    }
255	    store.bookings.push({
256	      id: b.id,
257	      resourceIds: [...(ids as string[])].sort(),
258	      start: b.start,
259	      end: b.end,
260	      status: b.status,
261	    });
262	    const n = Number(b.id.slice(1));
263	    if (n > store.bookingSeq) store.bookingSeq = n;
264	  });
265	
266	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
267	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
268	  return store;
269	}
270	
271	async function loadStore(file: string): Promise<Store> {
272	  let text: string;
273	  try {
274	    text = await readFile(file, 'utf8');
275	  } catch (err) {
276	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
277	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
278	  }
279	  let raw: unknown;
280	  try {
281	    raw = JSON.parse(text);
282	  } catch (err) {
283	    throw new BizError(
284	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
285	    );
286	  }
287	  return validateStore(raw, file);
288	}
289	
290	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
291	async function saveStore(file: string, store: Store): Promise<void> {
292	  let json: string;
293	  try {
294	    json = JSON.stringify(store, null, 2) + '\n';
295	  } catch (err) {
296	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
297	  }
298	  const tmp = `${file}.${process.pid}.tmp`;
299	  try {
300	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
301	    await rename(tmp, file);
302	  } catch (err) {
303	    await unlink(tmp).catch(() => {});
304	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
305	  }
306	}
307	
308	// ---------------------------------------------------------------------------
309	// 业务校验
310	// ---------------------------------------------------------------------------
311	
312	function formatResourceIds(store: Store, ids: string[]): string {
313	  return ids
314	    .map((id) => {
315	      const r = store.resources.find((x) => x.id === id);
316	      return r ? `${id}（${r.name}）` : id;
317	    })
318	    .join('、');
319	}
320	
321	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
322	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
323	  const problems: string[] = [];
324	  const seen = new Set<string>();
325	  const dupes: string[] = [];
326	  for (const id of rawIds) {
327	    if (seen.has(id)) {
328	      if (!dupes.includes(id)) dupes.push(id);
329	    }
330	    seen.add(id);
331	  }
332	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
333	
334	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
335	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
336	
337	  if (problems.length > 0) throw new BizError(problems.join('\n'));
338	  return [...seen].sort();
339	}
340	
341	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
342	  return mergeIntervals(
343	    r.open.map(
344	      ([s, e]) =>
345	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
346	    ),
347	  );
348	}
349	
350	// 校验每个资源的开放区间都能完整覆盖 [startMin, endMin)
351	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
352	  const failing = ids
353	    .map((id) => ({id, r: store.resources.find((x) => x.id === id)!}))
354	    .filter(({r}) => !isFullyCovered(openSegmentsOf(r), startMin, endMin));
355	  if (failing.length > 0) {
356	    throw new BizError(
357	      '开放时间不足，以下资源的开放区间不能完整覆盖预约区间：\n' +
358	        failing.map(({id, r}) => `- ${id}（${r.name}）`).join('\n'),
359	    );
360	  }
361	}
362	
363	interface Conflict {
364	  booking: BookingRec;
365	  shared: string[];
366	}
367	
368	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
369	function findConflicts(
370	  store: Store,
371	  ids: string[],
372	  startMin: number,
373	  endMin: number,
374	  excludeBookingId?: string,
375	): Conflict[] {
376	  const wanted = new Set(ids);
377	  const conflicts: Conflict[] = [];
378	  for (const b of store.bookings) {
379	    if (b.status !== 'active') continue;
380	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
381	    const bStart = parseDateTime(b.start, '预约开始时间');
382	    const bEnd = parseDateTime(b.end, '预约结束时间');
383	    const overlap = bStart < endMin && startMin < bEnd;
384	    if (!overlap) continue;
385	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
386	    if (shared.length > 0) conflicts.push({booking: b, shared});
387	  }
388	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
389	  return conflicts;
390	}
391	
392	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
393	  if (conflicts.length === 0) return;
394	  const lines = conflicts.map(
395	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
396	  );
397	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
398	}
