400	// ---------------------------------------------------------------------------
401	// 命令行解析
402	// ---------------------------------------------------------------------------
403	
404	interface GlobalArgs {
405	  dataFile: string;
406	  help: boolean;
407	  rest: string[];
408	}
409	
410	function splitGlobalArgs(argv: string[]): GlobalArgs {
411	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
412	  for (let i = 0; i < argv.length; i++) {
413	    const a = argv[i];
414	    if (a === '-h' || a === '--help') {
415	      result.help = true;
416	    } else if (a === '--data') {
417	      const v = argv[++i];
418	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
419	      result.dataFile = v;
420	    } else if (a.startsWith('--data=')) {
421	      result.dataFile = a.slice('--data='.length);
422	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
423	    } else {
424	      result.rest.push(a);
425	    }
426	  }
427	  return result;
428	}
429	
430	interface ParsedFlags {
431	  values: Map<string, string[]>;
432	  positionals: string[];
433	}
434	
435	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
436	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
437	  const allowedSet = new Set(allowed);
438	  const multiSet = new Set(multi);
439	  const values = new Map<string, string[]>();
440	  const positionals: string[] = [];
441	
442	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
443	    if (inline !== undefined) return [inline, index];
444	    const v = args[index + 1];
445	    if (v === undefined || v.startsWith('-')) {
446	      throw new UsageError(`选项 --${key} 缺少值`);
447	    }
448	    return [v, index + 1];
449	  };
450	
451	  for (let i = 0; i < args.length; i++) {
452	    const a = args[i];
453	    if (a.startsWith('--')) {
454	      let key: string;
455	      let inline: string | undefined;
456	      const eq = a.indexOf('=');
457	      if (eq >= 0) {
458	        key = a.slice(2, eq);
459	        inline = a.slice(eq + 1);
460	      } else {
461	        key = a.slice(2);
462	      }
463	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
464	      let v: string;
465	      [v, i] = takeValue(key, inline, i);
466	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
467	      if (!multiSet.has(key) && values.has(key)) {
468	        throw new UsageError(`选项 --${key} 只能指定一次`);
469	      }
470	      const list = values.get(key) ?? [];
471	      list.push(v);
472	      values.set(key, list);
473	    } else if (a.startsWith('-') && a !== '-') {
474	      throw new UsageError(`未知参数: ${a}`);
475	    } else {
476	      positionals.push(a);
477	    }
478	  }
479	  return {values, positionals};
480	}
481	
482	function requireFlag(values: Map<string, string[]>, key: string): string {
483	  const v = values.get(key)?.[0];
484	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
485	  return v;
486	}
487	
488	// ---------------------------------------------------------------------------
489	// 子命令实现
490	// ---------------------------------------------------------------------------
491	
492	async function cmdAddResource(args: string[]): Promise<void> {
493	  const {values, positionals} = parseFlags(args, ['type', 'name', 'open'], ['open']);
494	  if (positionals.length > 0) throw new UsageError(`add-resource 不接受位置参数: ${positionals.join(' ')}`);
495	
496	  const typeRaw = requireFlag(values, 'type');
497	  const type = RESOURCE_TYPE_MAP[typeRaw];
498	  if (!type) {
499	    throw new BizError(`资源类型非法: “${typeRaw}”，应为 venue（场地）、equipment（设备）或 person（人员）`);
500	  }
501	  const name = requireFlag(values, 'name');
502	  if (name.trim() === '') throw new BizError('资源名称不能为空');
503	
504	  const openRaw = values.get('open');
505	  if (!openRaw || openRaw.length === 0) throw new UsageError('至少需要一个 --open 开放区间');
506	  const open: Array<[string, string]> = openRaw.map((v) => {
507	    const iv = parseOpenInterval(v);
508	    return [iv.start, iv.end];
509	  });
510	
511	  const file = activeDataFile;
512	  const store = await loadStore(file);
513	  // 全部校验通过后才生成标识、改内存、落盘
514	  store.resourceSeq += 1;
515	  const id = `R${String(store.resourceSeq).padStart(4, '0')}`;
516	  store.resources.push({id, type, name, open});
517	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
518	  await saveStore(file, store);
519	  console.log(`已添加资源 ${id}（${RESOURCE_TYPE_LABEL[type]}｜${name}）`);
520	}
521	
522	async function cmdListResources(): Promise<void> {
523	  const store = await loadStore(activeDataFile);
524	  if (store.resources.length === 0) {
525	    console.log('暂无资源。可使用 add-resource 登记场地、设备或人员。');
526	    return;
527	  }
528	  console.log(`资源（共 ${store.resources.length} 个）：`);
529	  for (const r of store.resources) {
530	    console.log(`- ${r.id} [${RESOURCE_TYPE_LABEL[r.type]}] ${r.name}`);
531	    for (const [s, e] of r.open) {
532	      console.log(`    开放: ${s} → ${e}`);
533	    }
534	  }
535	}
536	
537	async function cmdCreateBooking(args: string[]): Promise<void> {
538	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end'], ['resource']);
539	  if (positionals.length > 0) throw new UsageError(`create-booking 不接受位置参数: ${positionals.join(' ')}`);
540	
541	  const resourceArgs = values.get('resource');
542	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
543	  const startRaw = requireFlag(values, 'start');
544	  const endRaw = requireFlag(values, 'end');
545	
546	  const file = activeDataFile;
547	  const store = await loadStore(activeDataFile);
548	
549	  const ids = resolveResourceIds(store, resourceArgs);
550	  const startMin = parseDateTime(startRaw, '预约开始时间');
551	  const endMin = parseDateTime(endRaw, '预约结束时间');
552	  if (endMin <= startMin) {
553	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
554	  }
555	  assertOpenCoverage(store, ids, startMin, endMin);
556	  assertNoConflicts(findConflicts(store, ids, startMin, endMin), store);
557	
558	  // 校验全部通过，一次性占用全部资源并落盘
559	  store.bookingSeq += 1;
560	  const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
561	  store.bookings.push({id, resourceIds: ids, start: startRaw, end: endRaw, status: 'active'});
562	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
563	  await saveStore(file, store);
564	  console.log(`已创建预约 ${id}`);
565	  console.log(`  时间: ${startRaw} → ${endRaw}`);
566	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
567	}
568	
569	async function cmdRescheduleBooking(args: string[]): Promise<void> {
570	  const {values, positionals} = parseFlags(args, ['start', 'end', 'resource'], ['resource']);
571	  if (positionals.length !== 1) {
572	    throw new UsageError('用法: reschedule-booking <预约标识> [--start ...] [--end ...] [--resource ...]');
573	  }
574	  const id = positionals[0];
575	
576	  const file = activeDataFile;
577	  const store = await loadStore(file);
578	  const booking = store.bookings.find((b) => b.id === id);
579	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
580	  if (booking.status === 'cancelled') {
581	    throw new BizError(`预约 ${id} 已取消，不能改期`);
582	  }
583	
584	  const hasTime = values.has('start') || values.has('end');
585	  const hasResource = values.has('resource');
586	  if (!hasTime && !hasResource) {
587	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
588	  }
589	
590	  const startRaw = values.get('start')?.[0] ?? booking.start;
591	  const endRaw = values.get('end')?.[0] ?? booking.end;
592	  const startMin = parseDateTime(startRaw, '预约开始时间');
593	  const endMin = parseDateTime(endRaw, '预约结束时间');
594	  if (endMin <= startMin) {
595	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
596	  }
597	
598	  let ids: string[] = booking.resourceIds;
599	  if (hasResource) {
600	    const resourceArgs = values.get('resource')!;
601	    ids = resolveResourceIds(store, resourceArgs);
602	  }
603	
604	  assertOpenCoverage(store, ids, startMin, endMin);
605	  // 改期检查排除自身
606	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
607	
608	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变
609	  booking.start = startRaw;
610	  booking.end = endRaw;
611	  booking.resourceIds = ids;
612	  await saveStore(file, store);
613	  console.log(`已改期预约 ${id}（标识保持不变）`);
614	  console.log(`  时间: ${startRaw} → ${endRaw}`);
615	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
616	}
