638	}
639	
640	async function cmdListBookings(args: string[]): Promise<void> {
641	  const {values, positionals} = parseFlags(args, ['date']);
642	  if (positionals.length > 0) throw new UsageError(`list-bookings 不接受位置参数: ${positionals.join(' ')}`);
643	  const dateRaw = requireFlag(values, 'date');
644	  const dayStart = parseDate(dateRaw);
645	  const dayEnd = dayStart + 1440;
646	
647	  const store = await loadStore(activeDataFile);
648	  // 与该日 [00:00, 次日00:00) 相交即包含：跨日预约、已取消记录均在内
649	  const hits = store.bookings
650	    .filter((b) => {
651	      const s = parseDateTime(b.start, '预约开始时间');
652	      const e = parseDateTime(b.end, '预约结束时间');
653	      return s < dayEnd && e > dayStart;
654	    })
655	    .map((b) => ({b, startMin: parseDateTime(b.start, '预约开始时间')}))
656	    .sort((x, y) => x.startMin - y.startMin || x.b.id.localeCompare(y.b.id));
657	
658	  if (hits.length === 0) {
659	    console.log(`${dateRaw} 当天没有预约（含跨日与已取消记录）。`);
660	    return;
661	  }
662	  console.log(`${dateRaw} 当天的预约（共 ${hits.length} 条，含跨日与已取消）：`);
663	  for (const {b} of hits) {
664	    const status = b.status === 'active' ? '已预约' : '已取消';
665	    console.log(`- ${b.id} [${status}] ${b.start} → ${b.end}`);
666	    console.log(`    资源: ${formatResourceIds(store, b.resourceIds)}`);
667	  }
668	}
669	
670	// ---------------------------------------------------------------------------
671	// 帮助与入口
672	// ---------------------------------------------------------------------------
673	
674	const HELP_TEXT = `shiftbook —— 本地多资源单次预约
675	
676	用法:
677	  node app.ts [--data <数据文件>] <命令> [选项]
678	
679	全局选项:
680	  --data <文件>   本地 JSON 数据文件（默认: ${DEFAULT_DATA_FILE}）
681	                  文件不存在时按空数据处理；文件损坏或结构非法时报错并保留原文件
682	  -h, --help      显示本帮助
683	
684	资源命令:
685	  add-resource --type <venue|equipment|person> --name <名称> \\
686	      --open <YYYY-MM-DDTHH:mm/YYYY-MM-DDTHH:mm> [--open ...]
687	      登记场地/设备/人员（类型也可写 场地、设备、人员），返回稳定标识，如 R0001
688	  list-resources
689	      列出全部资源的标识、类型、名称与开放区间
690	
691	预约命令:
692	  create-booking --resource <标识> [--resource <标识> ...] \\
693	      --start <YYYY-MM-DDTHH:mm> --end <YYYY-MM-DDTHH:mm>
694	      一次占用全部所选资源，返回稳定标识，如 B0001
695	  reschedule-booking <预约标识> [--start <时间>] [--end <时间>] \\
696	      [--resource <标识> ...]
697	      修改时间和/或资源（出现 --resource 即整体替换资源集合），标识保持不变
698	  cancel-booking <预约标识>
699	      取消预约并释放全部资源；对已取消记录再次取消成功且无变化
700	  list-bookings --date <YYYY-MM-DD>
701	      列出与该日相交的预约（含跨日、已取消），按开始时间再按标识排序
702	
703	时间规则:
704	  日期时间格式 YYYY-MM-DDTHH:mm，查询日期 YYYY-MM-DD；
705	  为与机器时区无关的营业地时间，日期必须真实有效，结束晚于开始，允许跨日；
706	  区间左闭右开：一个预约的结束恰为另一预约的开始不算冲突；
707	  开放区间重叠或相接视为连续开放，预约须被每个所选资源的开放区间完整覆盖；
708	  仅当存在共同资源且时间重叠时预约才冲突。
709	
710	退出码:
711	  0  成功
712	  1  业务失败（名称为空、未知/重复资源、时间非法、开放不足、冲突、数据文件损坏等）
713	  2  用法错误（未知参数、缺少必需选项等）
714	
715	示例:
716	  node app.ts add-resource --type 场地 --name 一号会议室 \\
717	      --open 2026-10-05T09:00/2026-10-05T18:00
718	  node app.ts create-booking --resource R0001 \\
719	      --start 2026-10-05T10:00 --end 2026-10-05T11:00
720	  node app.ts reschedule-booking B0001 --start 2026-10-05T14:00 --end 2026-10-05T15:00
721	  node app.ts list-bookings --date 2026-10-05
722	  node app.ts cancel-booking B0001
723	`;
724	
725	let activeDataFile = DEFAULT_DATA_FILE;
726	
727	async function main(): Promise<void> {
728	  const globalArgs = splitGlobalArgs(process.argv.slice(2));
729	  activeDataFile = globalArgs.dataFile;
730	
731	  if (globalArgs.help || globalArgs.rest.length === 0) {
732	    process.stdout.write(HELP_TEXT);
733	    return;
734	  }
735	
736	  const [command, ...commandArgs] = globalArgs.rest;
737	  switch (command) {
738	    case 'add-resource':
739	      await cmdAddResource(commandArgs);
740	      break;
741	    case 'list-resources':
742	      await cmdListResources();
743	      break;
744	    case 'create-booking':
745	      await cmdCreateBooking(commandArgs);
746	      break;
747	    case 'reschedule-booking':
748	      await cmdRescheduleBooking(commandArgs);
749	      break;
750	    case 'cancel-booking':
751	      await cmdCancelBooking(commandArgs);
752	      break;
753	    case 'list-bookings':
754	      await cmdListBookings(commandArgs);
755	      break;
756	    default:
757	      throw new UsageError(`未知命令: ${command}`);
758	  }
759	}
760	
761	main().catch((err: unknown) => {
762	  if (err instanceof UsageError) {
763	    process.stderr.write(`${APP}: ${err.message}\n使用 --help 查看用法。\n`);
764	    process.exit(2);
765	  }
766	  const message = err instanceof BizError ? err.message : (err as Error).stack ?? String(err);
767	  process.stderr.write(`${APP}: ${message}\n`);
768	  process.exit(1);
769	});
